<style>
    .sp-account{width:min(460px,100%);margin:auto;padding:30px;border:1px solid #14594c;border-radius:24px;background:#062924;color:#e7f4ef;box-sizing:border-box}
    .sp-account .brand{color:#27c99c;font-size:12px;letter-spacing:.1em;text-transform:uppercase}.sp-account h1{font-size:28px;line-height:1.2;margin:10px 0 16px}.sp-account p{line-height:1.6;color:#b4d0c7}
    .sp-account label{display:block;font-size:14px;margin:20px 0 8px}.sp-account input:not([type=hidden]){width:100%;box-sizing:border-box;padding:13px 14px;border:1px solid #2a6658;border-radius:12px;background:#03251f;color:#e7f4ef;outline:none}
    .sp-account input:focus{border-color:#23c79b;box-shadow:0 0 0 3px #23c79b22}.sp-account input::placeholder{color:#80a69b}
    .sp-account button{width:100%;margin-top:24px;padding:14px;border:0;border-radius:12px;background:#23c79b;color:#002d23;font-weight:700;cursor:pointer}
    .sp-account .secondary{background:transparent;border:1px solid #2a6658;color:#b4d0c7;margin-top:12px}.sp-account a{color:#47dab1;text-decoration:underline}.sp-account .back{display:block;text-align:center;margin-top:24px}
    .sp-account .error{color:#ffb5ac;font-size:14px}.sp-account .notice{padding:12px;border:1px solid #246b59;border-radius:10px;font-size:14px}
    @media(max-width:480px){.sp-account{padding:24px}.sp-account h1{font-size:25px}}
</style>
